@SubscribeEvent
static void registerScreens(RegisterMenuScreensEvent event) {
    event.register(MyMenus.MY_MENU.get(), MyMenuScreen::new);
}

@SubscribeEvent
static void registerShaders(RegisterShadersEvent event) throws IOException {
    ShaderInstance shader = new ShaderInstance(event.getResourceProvider(), new ResourceLocation("mymod", "my_shader"), DefaultVertexFormat.NEW_ENTITY);
    event.registerShader(shader, loaded -> MyClientShaders.MY_SHADER = loaded);
}
